erSchema("TransaccionID")]        [GraphQLDescription("TransaccionID")]        public int? TransaccionID { get; set; }        [SwaggerSchema("DocumentoID")]        [GraphQLDescription("DocumentoID")]        public int? DocumentoID { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}